<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='GET'){$slug=trim($_GET['slug']??'');if(!$slug){http_response_code(422);exit(json_encode(['error'=>'Post slug required.']));}$viewer=currentUser($pdo);$q=$pdo->prepare("SELECT c.id,c.body,c.created_at,c.updated_at,u.id user_id,u.name,u.bio FROM comments c JOIN users u ON u.id=c.user_id WHERE c.post_slug=? AND c.status='visible' ORDER BY c.created_at ASC");$q->execute([$slug]);$rows=$q->fetchAll();foreach($rows as &$row){$row['can_delete']=$viewer&&((int)$viewer['id']===(int)$row['user_id']||in_array($viewer['role'],['admin','editor'],true));}exit(json_encode(['data'=>$rows,'viewer'=>$viewer?['id'=>$viewer['id'],'name'=>$viewer['name']]:null]));}
$user=requireUser($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){$d=input();$slug=slugify($d['slug']??'');$body=trim($d['body']??'');if(!$slug||mb_strlen($body)<2||mb_strlen($body)>2000){http_response_code(422);exit(json_encode(['error'=>'Write a comment between 2 and 2,000 characters.']));}$q=$pdo->prepare('INSERT INTO comments(post_slug,user_id,body) VALUES(?,?,?)');$q->execute([$slug,$user['id'],$body]);$commentId=$pdo->lastInsertId();$owner=$pdo->prepare('SELECT user_id,title FROM posts WHERE slug=? AND user_id IS NOT NULL LIMIT 1');$owner->execute([$slug]);if($post=$owner->fetch()){if((int)$post['user_id']!==(int)$user['id']){$n=$pdo->prepare('INSERT INTO notifications(user_id,type,message,link) VALUES(?,"comment",?,?)');$n->execute([$post['user_id'],$user['name'].' commented on “'.$post['title'].'”','/article/'.$slug]);}}http_response_code(201);exit(json_encode(['ok'=>true,'id'=>$commentId]));}
if($_SERVER['REQUEST_METHOD']==='DELETE'){$id=(int)($_GET['id']??0);if(in_array($user['role'],['admin','editor'],true)){$q=$pdo->prepare('DELETE FROM comments WHERE id=?');$q->execute([$id]);}else{$q=$pdo->prepare('DELETE FROM comments WHERE id=? AND user_id=?');$q->execute([$id,$user['id']]);}exit(json_encode(['ok'=>true]));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
